                      src={review.imageUrl} 
                      alt={`تقييم ${review.studentName}`}
                      className="w-full h-auto rounded-lg shadow-sm"
                      style={{ maxHeight: '600px', minHeight: '400px', objectFit: 'contain' }}
                      onError={(e) => {
                        console.log('❌ Image failed to load:', review.imageUrl);
